def document(title: str, body: str) -> HTMLResponse:
    return HTMLResponse(
        '<!doctype html><html lang="en"><meta charset="utf-8">'
        '<meta name="viewport" content="width=device-width, initial-scale=1">'
        f'<title>{escape(title)}</title>'
        '<style>body{max-width:850px;margin:40px auto;padding:0 24px;'
        'font:16px/1.6 system-ui;color:#172125;background:#fff}'
        'pre{white-space:pre-wrap;font:inherit;overflow-wrap:anywhere}</style>'
        f'<main><pre>{escape(body)}</pre></main></html>'
    )


@router.get("/legal/android/privacy", response_class=HTMLResponse, include_in_schema=False)
async def android_privacy() -> HTMLResponse:
    return document("ChartAgent Android Privacy Policy", PRIVACY)


@router.get("/legal/android/terms", response_class=HTMLResponse, include_in_schema=False)
async def android_terms() -> HTMLResponse:
    return document("ChartAgent Android Terms of Use", TERMS)

